export function checkpointDuration(input={}){const f={...checkpointDefaults,...input};return checkpointStages.reduce((n,s)=>n+(f.checkpointSceneDurations[s.id]??s.duration),0)/f.checkpointRate;}
export function checkpointSourceToLocal(source,input={}){const f={...checkpointDefaults,...input};let n=0;for(const s of checkpointStages){const d=f.checkpointSceneDurations[s.id]??s.duration;if(source<=s.to)return(n+d*C((source-s.from)/s.duration))/f.checkpointRate;n+=d;}return n/f.checkpointRate;}
export function checkpointState(age,input={}){const f={...checkpointDefaults,...input};let n=0;for(const s of checkpointStages){const d=f.checkpointSceneDurations[s.id]??s.duration;if(age*f.checkpointRate<n+d)return{source:M(s.from,s.to,C((age*f.checkpointRate-n)/d)),id:s.id};n+=d;}return{source:900,id:checkpointStages.at(-1).id};}
function blendPose(a,b,q){return Object.fromEntries(Object.keys(a).map(k=>[k,mix(a[k],b[k]||a[k],q)]));}
function localPose(x,z,yaw,points){return Object.fromEntries(Object.entries(points).map(([k,[a,b,c]])=>[k,[x+a*Math.cos(yaw)+c*Math.sin(yaw),b,z-a*Math.sin(yaw)+c*Math.cos(yaw)]]));}
function seatedPose(pos){return localPose(pos[0],pos[2],-Math.PI/2+.3,{pelvis:[0,.8,0],chest:[0,1.35,.04],neck:[0,1.64,.05],head:[0,1.81,.05],leftShoulder:[-.3,1.52,.04],rightShoulder:[.3,1.52,.04],leftElbow:[-.35,1.20,.32],rightElbow:[.35,1.20,.32],leftWrist:[-.2,.95,.50],rightWrist:[.2,.95,.50],leftKnee:[-.18,.60,.58],rightKnee:[.18,.60,.58],leftAnkle:[-.18,.1,.65],rightAnkle:[.18,.1,.65]});}
