const surfaces=new Map();function surface(id,w=960,h=540){if(!surfaces.has(id))surfaces.set(id,Object.assign(document.createElement('canvas'),{width:w,height:h}));return surfaces.get(id);}
function layer(c,f,id,t,r,draw){const e=f.checkpointLayerEdits[id]||{};if(e.visible===false)return;const m=sampleObjectMotion((t-895)/f.checkpointRate,e.motion||{}),[x,y,w,h]=r;c.save();c.translate(x+w/2+(e.x||0)+m.x,y+h/2+(e.y||0)+m.y);c.rotate(((e.rotation||0)+m.rotation)*Math.PI/180);c.scale((e.scale??1)*m.scale,(e.scale??1)*m.scale);c.globalAlpha*=(e.opacity??1)*m.opacity;if(e.blur)c.filter=`blur(${e.blur}px)`;draw(-w/2,-h/2,w,h);recordSceneAsset(c,{id:'checkpoint:'+id,editKey:id,assetSlot:checkpointLayerCatalog.find(l=>l.id===id)?.slot,name:id,kind:'checkpoint'},[-w/2,-h/2,w,h]);c.restore();}
function rigLayer(scene,f,id,t,draw){const e=f.checkpointLayerEdits[id]||{};if(e.visible===false)return;const m=sampleObjectMotion((t-895)/f.checkpointRate,e.motion||{}),n=scene.commands.length;draw();for(const cmd of scene.commands.slice(n))cmd.edit={id,x:(e.x||0)+m.x,y:(e.y||0)+m.y,scale:(e.scale??1)*m.scale,rotation:(e.rotation||0)+m.rotation,opacity:(e.opacity??1)*m.opacity,blur:e.blur||0};}
