const crops=new WeakMap();function boot(images,f){const im=images[f.checkpointSourceBindings.checkpointBoot||'checkpointBoot'];if(!im||im.tagName==='VIDEO'&&im.readyState<2)return null;if(f.checkpointSourceBindings.checkpointBoot)return im;if(crops.has(im))return crops.get(im);const r=[.0096200096,.1917989418,.481962482,.633597884],cv=Object.assign(document.createElement('canvas'),{width:Math.round(im.width*r[2]),height:Math.round(im.height*r[3])});cv.getContext('2d').drawImage(im,im.width*r[0],im.height*r[1],im.width*r[2],im.height*r[3],0,0,cv.width,cv.height);crops.set(im,cv);return cv;}
