export function paintCheckpoint(c,age,images,input={}){const f={...checkpointDefaults,...input},state=checkpointState(age,f),t=state.source;if(age<0||!f.checkpointEnabled)return state;c.save();c.canvas.sceneAssets=[];if(f.checkpointNative3DEnabled&&globalThis.MotionNative3D?.paintCheckpoint){try{globalThis.MotionNative3D.paintCheckpoint(c,t,f);c.restore();return state;}catch(error){globalThis.native3DRenderError=error.message;}}if(f.checkpointRefinementEnabled){const focus=checkpointPose(t,f).defocus;if(focus>0&&f.checkpointLayerEdits.defocus?.visible!==false){const cv=surface('v88-refined'),pc=cv.getContext('2d');pc.reset?.();paintRefinement(pc,t,f);pc.getImageData(0,0,1,1);c.filter=`blur(${focus*4}px)`;c.drawImage(cv,0,0);}else paintRefinement(c,t,f);c.restore();return state;}if(age===0){paintOpportunity(c,opportunityDuration(input),images,input);c.restore();return state;}c.fillStyle='#000';c.fillRect(0,0,960,540);c.translate(480-f.checkpointCameraX,270-f.checkpointCameraY);c.scale(1+f.checkpointCameraZoom,1+f.checkpointCameraZoom);c.translate(-480,-270);const p=checkpointPose(t,f);if(p.defocus>0&&f.checkpointLayerEdits.defocus?.visible!==false){const cv=surface('scene'),pc=cv.getContext('2d');pc.reset?.();pc.clearRect(0,0,960,540);drawScene(pc,t,images,f,p);layer(c,f,'defocus',t,[0,0,960,540],(x,y)=>{c.filter=`blur(${p.defocus*12}px)`;c.drawImage(cv,x-12,y-7,984,554);});}else drawScene(c,t,images,f,p);if(f.checkpointIllustrationLabel)layer(c,f,'illustration-label',t,[12,522,800,12],(x,y)=>{c.font='7px Arial';c.fillStyle='#ddd8';c.fillText('ILLUSTRATIVE RECONSTRUCTION · AUTHORED RIGS / APPROXIMATE ACTING AND CAMERA',x,y);});c.restore();return state;}
